package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.Mockito.*;

/**
 * Unit tests for JsonParserSequence#nextToken
 */
public class JsonParserSequence_nextToken_TriageGen2Test {

    /**
     * Since JsonParserSequence has a protected constructor and the method 
     * switchToNext() is protected, we use a Testable subclass to expose 
     * the internal state and control the switching logic.
     */
    private static class TestableJsonParserSequence extends JsonParserSequence {
        private boolean forceSwitchToNext = false;
        private boolean delegateIsNull = false;
        private boolean suppressNextTokenFlag = false;

        protected TestableJsonParserSequence(JsonParser... parsers) {
            super(parsers);
        }

        // We need to simulate the internal state because the fields are private in the original class
        // However, since we can't modify the original class, we simulate the behavior 
        // by mocking the delegate/parsers or using reflection if necessary.
        // For this test, we will use Mockito to mock the JsonParser array.

        @Override
        protected boolean switchToNext() {
            return forceSwitchToNext;
        }

        public void setForceSwitchToNext(boolean force) {
            this.forceSwitchToNext = force;
        }

        public void setSuppressNextToken(boolean suppress) {
            this.suppressNextTokenFlag = suppress;
        }
    }

    // Because the fields 'delegate' and '_suppressNextToken' are private and 
    // 'switchToNext' is protected, we will use a Mockito-based approach 
    // with a subclass to facilitate testing the logic.

    private static class MockableJsonParserSequence extends JsonParserSequence {
        private final JsonParser[] parsers;

        protected MockableJsonParserSequence(JsonParser[] parsers) {
            super(parsers);
            this.parsers = parsers;
        }

        // We override switchToNext to control the while loop
        private int switchCount = 0;
        private int maxSwitches = 0;

        @Override
        protected boolean switchToNext() {
            if (switchCount < maxSwitches) {
                switchCount++;
                return true;
            }
            return false;
        }

        public void setMaxSwitches(int maxSwitches) {
            this.maxSwitches = maxSwitches;
        }

        // Use reflection to set the private _suppressNextToken field for testing
        public void setSuppressNextToken(boolean suppress) throws Exception {
            java.lang.reflect.Field field = JsonParserSequence.class.getDeclaredField("_suppressNextToken");
            field.setAccessible(true);
            field.set(this, suppress);
        }

        // Use reflection to set the private delegate field to null for testing
        public void setDelegateNull(boolean isNull) throws Exception {
            java.lang.reflect.Field field = JsonParserSequence.class.getDeclaredField("delegate");
            field.setAccessible(true);
            field.set(this, isNull ? null : parsers[0]);
        }
    }

    @Test
    public void testNextToken_DelegateIsNull() throws Exception {
        JsonParser mockParser = mock(JsonParser.class);
        MockableJsonParserSequence sequence = new MockableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setDelegateNull(true);

        assertNull(sequence.nextToken());
    }

    @Test
    public void testNextToken_SuppressNextTokenIsTrue() throws Exception {
        JsonParser mockParser = mock(JsonParser.class);
        when(mockParser.currentToken()).thenReturn(JsonToken.START_OBJECT);

        MockableJsonParserSequence sequence = new MockableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setSuppressNextToken(true);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.START_OBJECT, result);
        verify(mockParser, times(1)).currentToken();

        // Verify _suppressNextToken is reset to false
        java.lang.reflect.Field field = JsonParserSequence.class.getDeclaredField("_suppressNextToken");
        field.setAccessible(true);
        assertEquals(false, field.get(sequence));
    }

    @Test
    public void testNextToken_NormalFlowNoSwitch() throws Exception {
        JsonParser mockParser = mock(JsonParser.class);
        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME);

        MockableJsonParserSequence sequence = new MockableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setSuppressNextToken(false);
        sequence.setMaxSwitches(0);

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.FIELD_NAME, result);
        verify(mockParser, times(1)).nextToken();
    }

    @Test
    public void testNextToken_WithSwitchToNextAndHasCurrentToken() throws Exception {
        JsonParser mockParser = mock(JsonParser.class);
        // First call to nextToken returns FIELD_NAME
        // Then switchToNext returns true
        // Then hasCurrentToken returns true, so it calls currentToken
        when(mockParser.nextToken()).thenReturn(JsonToken.FIELD_NAME);
        when(mockParser.hasCurrentToken()).thenReturn(true);
        when(mockParser.currentToken()).thenReturn(JsonToken.VALUE_STRING);

        MockableJsonParserSequence sequence = new MockableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setMaxSwitches(1); 

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.VALUE_STRING, result);
        verify(mockParser).nextToken();
        verify(mockParser).hasCurrentToken();
        verify(mockParser).currentToken();
    }

    @Test
    public void testNextToken_WithSwitchToNextAndNoHasCurrentToken() throws Exception {
        JsonParser mockParser = mock(JsonParser.class);
        // First call to nextToken returns FIELD_NAME
        // Then switchToNext returns true
        // Then hasCurrentToken returns false, so it calls nextToken again
        when(mockParser.nextToken())
                .thenReturn(JsonToken.FIELD_NAME)
                .thenReturn(JsonToken.VALUE_NUMBER_INT);
        when(mockParser.hasCurrentToken()).thenReturn(false);

        MockableJsonParserSequence sequence = new MockableJsonParserSequence(new JsonParser[]{mockParser});
        sequence.setMaxSwitches(1); 

        JsonToken result = sequence.nextToken();

        assertEquals(JsonToken.VALUE_NUMBER_INT, result);
        verify(mockParser, times(2)).nextToken();
        verify(mockParser).hasCurrentToken();
    }
}
